<ol>
<li><strong>URL</strong>\uFF1A\u6807\u8BC6\u8D44\u6E90\uFF0C\u4F8B\u5982 <code dir="auto">/users/123</code></li>
<li><strong>HTTP \u65B9\u6CD5</strong>\uFF1A\u5B9A\u4E49\u64CD\u4F5C\uFF0C\u4F8B\u5982 <code dir="auto">GET</code> \u67E5\u8BE2\u3001<code dir="auto">PUT</code> \u66F4\u65B0</li>
<li><strong>Headers</strong>\uFF1A\u9644\u52A0\u4FE1\u606F\uFF0C\u6BD4\u5982\u5185\u5BB9\u683C\u5F0F\uFF08<code dir="auto">Content-Type: application/json</code>\uFF09\u3001\u8BA4\u8BC1\u4EE4\u724C\uFF08<code dir="auto">Authorization: Bearer ...</code>\uFF09</li>
<li><strong>\u8BF7\u6C42\u4F53\uFF08Body\uFF09</strong>\uFF1A\u5BF9\u4E8E <code dir="auto">POST/PUT</code> \u8BF7\u6C42\uFF0C\u901A\u5E38\u5305\u542B JSON \u6570\u636E</li>
</ol>
